1	'use strict';
2	
3	const { createHash } = require('node:crypto');
4	const { ConflictError, IntegrityError, NotFoundError, ValidationError } = require('./errors');
5	const replay = require('./replay');
6	const sim = require('./sim');
7	const { Store } = require('./store');
8	
9	/** Canonical JSON used to compare an idempotent retry with the original request. */
10	function canonicalJson(value) {
11	  if (Array.isArray(value)) {
12	    return `[${value.map(canonicalJson).join(',')}]`;
13	  }
14	  if (value && typeof value === 'object') {
15	    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
16	  }
17	  return JSON.stringify(value === undefined ? null : value);
18	}
19	
20	function requestHash(body) {
21	  return createHash('sha256').update(canonicalJson(body)).digest('hex');
22	}
23	
24	/**
25	 * LockstepNet service: deterministic lockstep simulation with rollback replay.
26	 *
27	 * The whole contract follows from three rules:
28	 *   1. a match state is a pure function of (configuration, set of input records);
29	 *   2. an input record is keyed by (tick, unit, command) and applied in a
30	 *      canonical order inside its tick, so arrival order is irrelevant;
31	 *   3. an input for a tick that already ran forces a rollback: the frames from
32	 *      that tick on are rebuilt by replaying the stored input log, which
33	 *      reproduces the hashes that were recorded before the rollback.
34	 */
35	class Lockstep {
36	  constructor(database) {
37	    this.store = new Store(database);
38	  }
39	
40	  close() {
41	    this.store.close();
42	  }
43	
44	  /** Required-key idempotency: repeats return the first result, conflicts are 409. */
45	  idempotent(key, operation, body, action) {
46	    if (typeof key !== 'string' || key.length === 0 || key.length > 200) {
47	      throw new ValidationError('Idempotency-Key header must be a non-empty string of at most 200 characters');
48	    }
49	    const hash = requestHash(body);
50	    return this.store.transaction(() => {
51	      const existing = this.store.getIdempotent(key);
52	      if (existing) {
53	        if (existing.operation !== operation) {
54	          throw new ConflictError('idempotency key was already used for another operation');
55	        }
56	        if (existing.requestHash !== hash) {
57	          throw new ConflictError('idempotency key was already used with a different request body');
58	        }
59	        return existing.response;
60	      }
61	      const response = action();
62	      this.store.putIdempotent(key, operation, hash, response);
63	      return response;
64	    });
65	  }
66	
67	  match(matchId) {
68	    const record = this.store.readMatch(matchId);
69	    if (!record) {
70	      throw new NotFoundError(`match ${matchId} was not found`);
71	    }
72	    return record;
73	  }
74	
75	  config(matchId) {
76	    return this.match(matchId).config;
77	  }
78	
79	  createMatch(raw, key) {
80	    const config = sim.parseConfig(raw);
81	    return this.idempotent(key, `create-match:${config.id}`, raw, () => {
82	      if (this.store.readMatch(config.id)) {
83	        throw new ConflictError(`match ${config.id} already exists`);
84	      }
85	      const state = sim.initialState(config);
86	      state.hash = sim.stateHash(state);
87	      this.store.insertMatch(config, state);
88	      return this.describe(config, state);
89	    });
90	  }
91	
92	  getState(matchId) {
93	    const record = this.match(matchId);
94	    return this.describe(record.config, this.store.readState(matchId));
95	  }
96	
97	  /**
98	   * Public projection of a match: configuration, current deterministic state and
99	   * input-delivery counters.
100	   *
101	   * `missing` counts the input records the match expected but never received:
102	   * one per unit alive at the start of each already simulated tick, minus the
103	   * records that were delivered for that tick.
104	   */
105	  describe(config, state) {
106	    const frames = this.store.readFrames(config.id);
107	    const stats = this.store.readStats(config.id);
108	    let missing = 0;
109	    let settled = 0;
110	    for (const frame of frames) {
111	      const gap = Math.max(0, frame.alive - frame.inputs.length);
112	      missing += gap;
113	      settled += gap === 0 ? 1 : 0;
114	    }
115	    const alive = Object.values(state.units).filter((unit) => unit.health > 0);
116	    const team = (name) => ({ alive: alive.filter((unit) => unit.team === name).length, damage: state.teamDamage[name] });
117	    return {
118	      config: { id: config.id, max_ticks: config.maxTicks, seed: config.seed, units: config.units },
119	      inputs: {
120	        accepted: stats.accepted, duplicates: stats.duplicates, missing,
121	        rejected: stats.rejected, rollbacks: stats.rollbacks, settled,
122	      },
123	      match_id: config.id,
124	      max_ticks: config.maxTicks,
125	      seed: config.seed,
126	      state_hash: state.hash,
127	      status: state.status,
128	      teams: { blue: team('blue'), red: team('red') },
129	      tick: state.tick,
130	      units: Object.values(state.units).sort((left, right) => (left.id < right.id ? -1 : 1)).map((unit) => ({
131	        alive: unit.health > 0, attacking: unit.attacking, health: unit.health,
132	        id: unit.id, position: unit.position, team: unit.team, velocity: unit.velocity,
133	      })),
134	    };
135	  }
136	
137	  /**
138	   * Queue input records. Records may arrive in any order, any number of times
139	   * and any number per request.
140	   *
141	   *  - a record whose (tick, unit, command) key is already stored is a
142	   *    duplicate: counted, never re-applied, and it cannot change the state;
143	   *  - a record for a tick beyond the frontier is stored for later;
144	   *  - a record for a tick at or below the frontier triggers one rollback to the
145	   *    earliest such tick, then a recomputation back to the frontier;
146	   *  - a record for an unknown unit, an out-of-range tick or a malformed command
147	   *    is rejected with a reason and leaves the state untouched.
148	   */
149	  submitInputs(matchId, raw, key) {
150	    const record = this.match(matchId);
151	    sim.exactKeys(raw, ['inputs'], 'body');
152	    if (!Array.isArray(raw.inputs)) {
153	      throw new ValidationError('inputs must be an array');
154	    }
155	    return this.idempotent(key, `submit-inputs:${matchId}`, raw, () => {
156	      if (raw.inputs.length === 0) {
157	        throw new ValidationError('inputs must be a non-empty array');
158	      }
159	      const frontier = this.store.readState(matchId).tick;
160	      const accepted = [];
161	      const duplicates = [];
162	      const rejected = [];
163	      let earliest = null;
164	      raw.inputs.forEach((entry, index) => {
165	        let input;
166	        try {
167	          input = sim.parseInputRecord(entry);
168	        } catch (error) {
169	          rejected.push({ index, message: error.message, reason: 'invalid_input' });
170	          return;
171	        }
172	        if (input.tick >= record.config.maxTicks) {
173	          rejected.push({
174	            index,
175	            message: `input tick ${input.tick} is outside the match length ${record.config.maxTicks}`,
176	            reason: 'out_of_range',
177	          });
178	          return;
179	        }
180	        if (!record.config.units.some((unit) => unit.id === input.unit)) {
181	          rejected.push({ index, message: `input references unknown unit ${input.unit}`, reason: 'unknown_unit' });
182	          return;
183	        }
184	        if (this.store.readInput(matchId, input.tick, input.unit, input.command.kind)) {
185	          duplicates.push({ command: input.command.kind, tick: input.tick, unit: input.unit });
186	          return;
187	        }
188	        input.arrival = this.store.countInputsBefore(matchId, record.config.maxTicks);
189	        this.store.insertInput(matchId, input, sim.stripInput(input));
190	        accepted.push({ command: input.command.kind, seq: input.seq, tick: input.tick, unit: input.unit });
191	        if (earliest === null || input.tick < earliest) {
192	          earliest = input.tick;
193	        }
194	      });
195	
196	      this.store.bumpStat(matchId, 'accepted', accepted.length);
197	      this.store.bumpStat(matchId, 'duplicates', duplicates.length);
198	      this.store.bumpStat(matchId, 'rejected', rejected.length);
199	
200	      let rollback = null;
201	      if (earliest !== null && earliest < frontier) {
202	        // A late input rewinds the match to the earliest affected tick and then
203	        // replays forward to the frontier it had reached before this request, so
204	        // accepting a late input never loses already simulated ticks.
205	        const rewound = this.rollback(matchId, earliest);
206	        const { frames } = this.resimulate(matchId, earliest, frontier, false);
207	        const after = this.store.readState(matchId);
208	        this.store.bumpStat(matchId, 'rollbacks', 1);
209	        rollback = { ...rewound, frames_recomputed: frames.length, hash_after: after.hash, tick: after.tick };
210	      }
211	      return {
212	        ...this.describe(record.config, this.store.readState(matchId)),
213	        accepted, duplicates, rejected, rollback,
214	      };
215	    });
216	  }
217	
218	  /**
219	   * Advance a match by `count` ticks (default 1).
220	   *
221	   * The frontier never passes `max_ticks`, and the simulation stops early when a
222	   * team is eliminated. Advancing a match that is not `running` is a 409.
223	   */
224	  advance(matchId, raw, key) {
225	    const config = this.config(matchId);
226	    const body = raw === undefined || raw === null ? { count: 1 } : raw;
227	    sim.exactKeys(body, ['count'], 'body');
228	    const count = body.count === undefined ? 1 : body.count;
229	    if (!Number.isInteger(count) || count < 1 || count > sim.MAX_STEP) {
230	      throw new ValidationError(`count must be an integer between 1 and ${sim.MAX_STEP}`);
231	    }
232	    return this.idempotent(key, `advance:${matchId}`, { count }, () => {
233	      const before = this.store.readState(matchId);
234	      if (before.status !== 'running') {
235	        throw new ConflictError(`match ${matchId} is ${before.status} and cannot advance`);
236	      }
237	      const target = Math.min(before.tick + count, config.maxTicks);
238	      const { frames } = this.resimulate(matchId, before.tick, target, false);
239	      const updated = this.store.readState(matchId);
240	      return {
241	        ...this.describe(config, updated),
242	        advanced: frames.length,
243	        frames: frames.map((frame) => ({
244	          casualties: frame.delta.casualties, settled: frame.settled,
245	          state_hash: frame.state_hash, tick: frame.tick,
246	        })),
247	        state_hash: updated.hash,
248	      };
249	    });
250	  }
251	
252	  /**
253	   * Explicit rollback: rewind the match to `tick` by discarding every frame after
254	   * it. Input records are never discarded, so the next `POST /tick` replays them
255	   * and reproduces exactly the hashes recorded before the rollback.
256	   */
257	  rollback(matchId, tick) {
258	    const record = this.match(matchId);
259	    if (!Number.isInteger(tick) || tick < 0 || tick > record.config.maxTicks) {
260	      throw new ValidationError(`tick must be an integer between 0 and ${record.config.maxTicks}`);
261	    }
262	    const before = this.store.readState(matchId);
263	    if (tick > before.tick) {
264	      throw new ConflictError(`tick ${tick} is past the current tick ${before.tick}`);
265	    }
266	    this.resimulate(matchId, tick, tick, false);
267	    const after = this.store.readState(matchId);
268	    return {
269	      frames_recomputed: before.tick - tick,
270	      from_tick: before.tick, hash_after: after.hash, hash_before: before.hash,
271	      match_id: matchId, tick: after.tick, to_tick: tick,
272	    };
273	  }
274	
275	  /** The whole match as a portable replay document. */
276	  replayFile(matchId) {
277	    const record = this.match(matchId);
278	    const frames = this.store.readFrames(matchId).map((frame) => ({
279	      delta: frame.delta, settled: frame.settled, settled_inputs: frame.inputs,
280	      state_hash: frame.state_hash, tick: frame.tick,
281	    }));
282	    return replay.buildFile(record.config, frames, this.store.readInputs(matchId));
283	  }
284	
285	  /**
286	   * `POST /matches/{id}/verify` accepts either `{"match_id": "..."}` to
287	   * re-simulate a stored match, or `{"replay": {...}}` for an uploaded replay.
288	   */
289	  verify(raw) {
290	    sim.exactKeys(raw, ['match_id', 'replay'], 'body');
291	    if (raw.replay !== undefined && raw.match_id !== undefined) {
292	      throw new ValidationError('provide either match_id or replay, not both');
293	    }
294	    if (raw.replay !== undefined) {
295	      return this.verifyDocument(raw.replay);
296	    }
297	    if (typeof raw.match_id !== 'string' || raw.match_id.length === 0) {
298	      throw new ValidationError('match_id must be a non-empty string');
299	    }
300	    return this.verifyDocument(this.replayFile(raw.match_id));
301	  }
302	
303	  verifyDocument(document) {
304	    const result = replay.verifyDocument(document);
305	    const stored = this.store.readMatch(result.config.id);
306	    const mismatches = result.mismatches.slice();
307	    let recordedHash = null;
308	    if (stored && stored.tick === result.state.tick) {
309	      recordedHash = stored.stateHash;
310	      if (recordedHash !== result.state_hash) {
311	        mismatches.push({
312	          kind: 'state_hash',
313	          message: 'replayed final state does not match the stored match state',
314	          recorded: recordedHash, recomputed: result.state_hash, tick: result.state.tick,
315	        });
316	      }
317	    }
318	    return {
319	      consistent: mismatches.length === 0,
320	      final_state_hash: result.state_hash,
321	      match_id: result.config.id,
322	      mismatches,
323	      recorded_state_hash: recordedHash,
324	      replay_hash: result.replay_hash,
325	      ticks_replayed: result.frames.length,
326	    };
327	  }
328	
329	  /**
330	   * Rebuild the frame log from `resumeTick` up to `targetTick`.
331	   *
332	   * Frames after `resumeTick` are discarded and re-derived from the snapshot at
333	   * `resumeTick` plus the stored input records. Every rebuilt frame that already
334	   * existed must keep its hash; a divergence means the log or the engine changed
335	   * and is reported as `integrity_failure` instead of silently changing results.
336	   *
337	   * `extend` lets the match simulate past `targetTick` until a team is eliminated
338	   * or `max_ticks` is reached. `POST /tick` does not extend: stopping exactly at
339	   * the requested tick is what makes rollback-then-advance reproduce hashes.
340	   */
341	  resimulate(matchId, resumeTick, targetTick, extend = false) {
342	    const config = this.config(matchId);
343	    if (targetTick < resumeTick) {
344	      throw new IntegrityError(`cannot resimulate ${matchId} backwards from ${resumeTick} to ${targetTick}`);
345	    }
346	    const expected = new Map();
