3	const { DatabaseSync } = require('node:sqlite');
4	
5	/**
6	 * Persistence built on the standard-library SQLite binding (`node:sqlite`, Node
7	 * 22.5+). It stores the match configuration, the *current* unit state, the
8	 * recorded frame log and the input records.
9	 *
10	 * The frame log is the replay artefact: inputs are keyed by
11	 * (match, tick, unit, command) and never discarded, while frames are keyed by
12	 * (match, tick) and are deleted and rebuilt by every rollback.
13	 */
14	const SCHEMA = `
15	  CREATE TABLE IF NOT EXISTS matches (
16	    id TEXT PRIMARY KEY, seed INTEGER NOT NULL, max_ticks INTEGER NOT NULL,
17	    tick INTEGER NOT NULL, status TEXT NOT NULL, state_hash TEXT,
18	    units_json TEXT NOT NULL
19	  );
20	  CREATE TABLE IF NOT EXISTS units (
21	    match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
22	    id TEXT NOT NULL, team TEXT NOT NULL, position INTEGER NOT NULL,
23	    velocity INTEGER NOT NULL, health INTEGER NOT NULL, attacking INTEGER NOT NULL,
24	    PRIMARY KEY (match_id, id)
25	  );
26	  CREATE TABLE IF NOT EXISTS teams (
27	    match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
28	    team TEXT NOT NULL, damage INTEGER NOT NULL,
29	    PRIMARY KEY (match_id, team)
30	  );
31	  CREATE TABLE IF NOT EXISTS frames (
32	    match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
33	    tick INTEGER NOT NULL, state_hash TEXT NOT NULL, delta_json TEXT NOT NULL,
34	    state_json TEXT NOT NULL, input_json TEXT NOT NULL, alive INTEGER NOT NULL,
35	    settled INTEGER NOT NULL,
36	    PRIMARY KEY (match_id, tick)
37	  );
38	  CREATE TABLE IF NOT EXISTS inputs (
39	    match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
40	    tick INTEGER NOT NULL, unit TEXT NOT NULL, command TEXT NOT NULL,
41	    seq INTEGER NOT NULL, arrival INTEGER NOT NULL, body_json TEXT NOT NULL,
42	    PRIMARY KEY (match_id, tick, unit, command)
43	  );
44	  CREATE TABLE IF NOT EXISTS stats (
45	    match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
46	    name TEXT NOT NULL, value INTEGER NOT NULL,
47	    PRIMARY KEY (match_id, name)
48	  );
49	  CREATE TABLE IF NOT EXISTS idempotency (
50	    key TEXT PRIMARY KEY, operation TEXT NOT NULL,
51	    request_hash TEXT NOT NULL, response_json TEXT NOT NULL
52	  );
53	`;
54	
55	function unitRow(unit) {
56	  return {
57	    attacking: unit.attacking, health: unit.health, id: unit.id,
58	    position: unit.position, team: unit.team, velocity: unit.velocity,
59	  };
60	}
61	
62	class Store {
63	  constructor(path) {
64	    this.connection = new DatabaseSync(path);
65	    this.connection.exec('PRAGMA journal_mode = WAL');
66	    this.connection.exec('PRAGMA foreign_keys = ON');
67	    this.connection.exec(SCHEMA);
68	  }
69	
70	  close() {
71	    this.connection.close();
72	  }
73	
74	  /** Run `body` inside a transaction; roll back on any throw. */
75	  transaction(body) {
76	    this.connection.exec('BEGIN IMMEDIATE');
77	    try {
78	      const value = body();
79	      this.connection.exec('COMMIT');
80	      return value;
81	    } catch (error) {
82	      try {
83	        this.connection.exec('ROLLBACK');
84	      } catch {
85	        /* the transaction was already closed */
