36	/**
37	 * Two units that never reach each other: red stays at 0, blue stays at 990. A
38	 * plain 8-tick match therefore always runs to exactly the tick that was asked
39	 * for, which keeps every frame-count assertion stable. `max_ticks` is far enough
40	 * away that rollback tests can rewind and re-advance freely.
41	 */
42	function matchConfig(overrides = {}) {
43	  return {
44	    id: 'match-1',
45	    max_ticks: 64,
46	    seed: 11,
47	    units: [
48	      { id: 'blue-1', position: 990, team: 'blue', velocity: 0 },
49	      { id: 'red-1', position: 0, team: 'red', velocity: 0 },
50	    ],
51	    ...overrides,
52	  };
53	}
