61	 * arrival order can be mistaken for the canonical one.
62	 */
63	const FULL_LOG = Object.freeze([
64	  input(0, 'red-1', { by: 3, kind: 'move' }),
65	  input(2, 'red-1', { kind: 'move', position: 120 }),
66	  input(4, 'red-1', { kind: 'move', velocity: 9 }),
67	  input(6, 'red-1', { by: -5, kind: 'move' }),
68	  input(1, 'red-1', { attacking: true, kind: 'attack' }),
69	  input(3, 'red-1', { attacking: false, kind: 'attack' }),
70	  input(5, 'red-1', { attacking: true, kind: 'attack' }),
71	  input(7, 'red-1', { attacking: true, kind: 'attack' }),
72	  input(0, 'blue-1', { kind: 'move', position: 500 }),
73	  input(2, 'blue-1', { kind: 'move', velocity: -3 }),
74	  input(4, 'blue-1', { by: 40, kind: 'move' }),
75	  input(6, 'blue-1', { kind: 'move', position: 480 }),
76	  input(0, 'blue-1', { attacking: true, kind: 'attack' }),
77	  input(2, 'blue-1', { attacking: true, kind: 'attack' }),
78	  input(6, 'blue-1', { attacking: true, kind: 'attack' }),
79	]);
