    rejects({ unexpected: true });
    rejects({ inputs: 'all' });
    rejects({ frames: [{ tick: 0, state_hash: 'x' }] });
    rejects({ frames: [{ inputs: [], state_hash: 'A'.repeat(64), tick: 1 }] });
    rejects({ match: { id: 'x', units: [] } });
