360	  resume(matchId, sessionId, raw, key) {
361	    this.match(matchId);
362	    this.requireSession(matchId, sessionId);
363	    const body = raw === undefined || raw === null ? {} : raw;
364	    sim.exactKeys(body, ['after_tick', 'limit'], 'body');
365	    const afterTick = body.after_tick === undefined ? 0 : body.after_tick;
366	    if (!Number.isInteger(afterTick) || afterTick < 0) {
367	      throw new ValidationError('after_tick must be a non-negative integer');
368	    }
369	    const limit = body.limit === undefined ? sim.MAX_STEP : body.limit;
370	    if (!Number.isInteger(limit) || limit < 1 || limit > sim.MAX_STEP) {
371	      throw new ValidationError(`limit must be an integer between 1 and ${sim.MAX_STEP}`);
372	    }
373	    const normalized = { after_tick: afterTick, limit };
374	    return this.idempotent(key, `session-resume:${matchId}:${sessionId}`, normalized, () => {
375	      const frontier = this.store.readState(matchId);
376	      if (afterTick > frontier.tick) {
377	        throw new ConflictError(`after_tick ${afterTick} is past the current tick ${frontier.tick}`);
378	      }
379	      const available = this.store.readFramesFrom(matchId, afterTick + 1);
380	      const frames = available.slice(0, limit);
381	      frames.forEach((frame, index) => {
382	        const expectedTick = afterTick + index + 1;
383	        if (frame.tick !== expectedTick) {
384	          throw new IntegrityError(
385	            `resume of match ${matchId} expected frame ${expectedTick} but the next frame is ${frame.tick}`,
386	          );
387	        }
388	      });
389	      const endTick = afterTick + frames.length;
390	      // When the window covers every frame the log still holds yet stops short
391	      // of the frontier, a trailing frame is missing rather than merely paged.
392	      const reachedLogEnd = frames.length === available.length;
393	      if (reachedLogEnd && endTick < frontier.tick) {
394	        throw new IntegrityError(
395	          `resume of match ${matchId} found no frame ${endTick + 1} but the frontier is ${frontier.tick}`,
396	        );
397	      }
398	      // The caught-up state is reconstructed from the recorded snapshot, so its
399	      // hash must reproduce the last delivered frame hash and the frontier hash
400	      // when the window reaches it.
401	      const caught = this.snapshotAt(matchId, endTick);
402	      caught.hash = sim.stateHash(caught);
403	      if (frames.length > 0 && caught.hash !== frames[frames.length - 1].state_hash) {
404	        throw new IntegrityError(
405	          `frame ${endTick} of match ${matchId} snapshot hashes to ${caught.hash} but was recorded as ${frames[frames.length - 1].state_hash}`,
406	        );
407	      }
408	      const complete = endTick === frontier.tick;
409	      if (complete && caught.hash !== frontier.hash) {
410	        throw new IntegrityError(
411	          `frame ${endTick} of match ${matchId} matches its frame hash but not the frontier hash ${frontier.hash}`,
412	        );
413	      }
414	      this.store.setSessionStatus(matchId, sessionId, 'connected');
415	      return {
416	        after_tick: afterTick,
417	        complete,
418	        frames: frames.map((frame) => ({
419	          casualties: frame.delta.casualties, settled: frame.settled,
420	          state_hash: frame.state_hash, tick: frame.tick,
421	        })),
422	        match_id: matchId,
423	        next_tick: endTick,
424	        session_id: sessionId,
